import sqlite3
import sys

db_path = "/data/maps/e2e_test_case_0.Civ6Map"

try:
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()

    print("Tables:")
    cursor.execute("SELECT name FROM sqlite_master WHERE type='table';")
    tables = cursor.fetchall()
    for t in tables:
        print(t[0])

    print("\nMetaData:")
    try:
        cursor.execute("SELECT * FROM MetaData;")
        for row in cursor.fetchall():
            print(row)
    except: print("No MetaData")

    print("\nMap:")
    try:
        cursor.execute("SELECT * FROM Map;")
        for row in cursor.fetchall():
            print(row)
    except: print("No Map table")

    print("\nPlotFeatures Schema:")
    cursor.execute("PRAGMA table_info(PlotFeatures);")
    for col in cursor.fetchall():
        print(col)

    print("\nPlotResources Schema:")
    cursor.execute("PRAGMA table_info(PlotResources);")
    for col in cursor.fetchall():
        print(col)

